contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking inputs to try openMake/openTake for an account
    function run(address account, uint256 amountRaw, bool makeNotTake) public payable {
        // use amountRaw to construct a UFixed18-like uint by treating it as raw; avoid zero specialcases
        uint256 amount = amountRaw == 0 ? 1 : amountRaw;

        // observe maintenanceNext before
        try c.maintenanceNext(account) returns (UFixed18 mnBefore) {
            // call will be attempted below
        } catch {
            // if view throws (shouldn't) just set a dummy by calling latestVersion getter instead
        }

        UFixed18 mnBefore = c.maintenanceNext(account);

        bool reverted;
        UFixed18 positionFee; // cannot read directly; we will infer via collateral.fees change by comparing before/after

        // observe collateral fees before (via controller.collateral().fees(account))
        address controllerAddr = address(c.controller());
        // call controller().collateral() to get address; it's external view so safe
        IController controller = c.controller();
        ICollateral coll = controller.collateral();

        UFixed18 feesBefore = coll.fees(account);

        // perform chosen action: openMakeFor or openTakeFor. Must be top-level state-changing call.
        if (makeNotTake) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // observe maintenanceNext after
        UFixed18 mnAfter = c.maintenanceNext(account);

        UFixed18 feesAfter = coll.fees(account);

        // If call succeeded, feesAfter should be <= feesBefore because position fees are charged as negative Fixed18 to settleAccount
        // But simpler general rule: when call succeeds, maintenanceNext does not decrease (mnAfter >= mnBefore)

        if (!reverted) {
            // assert non-decreasing maintenanceNext
            assert(mnAfter.gte(mnBefore));
        } else {
            // if reverted, we don't assert anything about maintenance changes; but still reach assert by encoding equivalence
            assert(reverted == true || mnAfter.gte(mnBefore));
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: account, amountRaw, and selector (0=openMakeFor,1=openTakeFor)
    function run(address account, uint256 amountRaw, uint8 kind) public payable {
        require(kind <= 1, "bad kind");
        // avoid zero amount to make the call meaningful
        uint256 amountValue = amountRaw == 0 ? 1 : amountRaw;

        // observe maintenanceNext before
        UFixed18 mnBefore = c.maintenanceNext(account);

        // prepare amount as UFixed18 by using UFixed18Lib.ONE * amountValue via public constructor functions are not available
        // but openMakeFor/openTakeFor accept UFixed18 which is a uint256 alias; pass raw value (tests treat it as opaque)
        UFixed18 amount = UFixed18.wrap(amountValue);

        // perform the chosen state-changing call as a single top-level statement
        if (kind == 0) {
            c.openMakeFor(account, amount);
        } else {
            c.openTakeFor(account, amount);
        }

        // observe maintenanceNext after
        UFixed18 mnAfter = c.maintenanceNext(account);

        // Single assert: if the call did not revert then maintenanceNext after >= before.
        // We cannot directly detect revert here because a revert would have aborted execution; thus reaching this assert implies the call succeeded.
        assert(mnAfter.gte(mnBefore));
    }

    receive() external payable {}
}

