contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an account address and an amount to open as maker. The contract will call openMakeFor(account, amount).
    // To satisfy onlyAccountOrMultiInvoker and onlyProductOwner modifiers not applicable here, we call openMake which uses msg.sender as account.
    // However openMakeFor requires msg.sender to be either account or multiInvoker; to avoid permission issues we will call openMake() so account==msg.sender (the test contract) and thus onlyAccountOrMultiInvoker is satisfied.
    // The test rule: if the call to openMake(amount) does NOT revert, then after the call latestVersion(address(this)) equals latestVersion() and the account is not closed (isClosed(account) == false).

    function run(uint256 amount) public payable {
        require(true);

        // read before-values
        uint256 beforeGlobal = c.latestVersion();
        uint256 beforeAccount = c.latestVersion(address(this));
        bool reverted;

        // attempt to open make for msg.sender by calling openMake(amount)
        try c.openMake(UFixed18.wrap(amount)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observables after call
        uint256 afterGlobal = c.latestVersion();
        uint256 afterAccount = c.latestVersion(address(this));
        bool accountClosed = c.isClosed(address(this));

        // General rule: if the call did not revert then the account's latestVersion must equal the global latestVersion
        // and the account must not be reported closed. This asserts a consistency property about successful state transitions.
        assert(reverted || (afterAccount == afterGlobal && accountClosed == false));
    }

    receive() external payable {}
}

contract InvMutTest {
