    // We call openMake() as msg.sender == this contract so onlyAccountOrMultiInvoker passes for the account
    // Parameter amount is the raw UFixed18 underlying value; require a small bound to avoid extreme overflow in helper libs
    function run(uint128 amount) public payable {
        require(amount > 0 && amount <= type(uint128).max/2);

        bool reverted;
        // single state-changing call at top level
        try c.openMake(UFixed18.wrap(uint256(amount))) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe public getters
        uint256 g = c.latestVersion();
        uint256 a = c.latestVersion(address(this));

        // If the openMake call did not revert then the account latestVersion must equal global latestVersion.
        assert(reverted || a == g);
    }

    receive() external payable {}
}

