contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test entry point. We take params to call either openTakeFor or openMakeFor.
    function run(address account, bool callMake, uint256 amountRaw) public payable {
        require(amountRaw <= type(uint128).max, "amount too large");
        // amountRaw represents UFixed18 raw value (as uint256 wrapper). We will pass it through by casting.
        // Record observable values before the mutating call
        uint256 beforeBalance = address(c).balance;

        // We will attempt the chosen call and detect whether it reverted.
        bool reverted;
        // There's no direct way to observe fees charged except via collateral.settleAccount which requires controller interactions.
        // But we can observe that the contract's Ether balance should not decrease as a result of charging a position fee (fees are accounted off-chain via controller collateral),
        // so we assert that address(c).balance >= beforeBalance after the call if it succeeded, and if it reverted then balance unchanged.

        // Make the mutating call as top-level statements.
        if (callMake) {
            // call openMakeFor
            try c.openMakeFor(account, UFixed18.wrap(amountRaw)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // call openTakeFor
            try c.openTakeFor(account, UFixed18.wrap(amountRaw)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterBalance = address(c).balance;

        // General rule: position fee charging should not reduce the product contract's Ether balance below its previous balance.
        // If call reverted then contract balance must remain exactly unchanged. If call succeeded then balance must be >= beforeBalance.
        assert((reverted && afterBalance == beforeBalance) || (!reverted && afterBalance >= beforeBalance));
    }

    receive() external payable {}
}

