contract InvMutTest {
    C c;
    IController controller;

    constructor(C _c) {
        c = _c;
        controller = c.controller();
    }

    // single public test function
    function run(address caller, bool newClosed) public payable {
        require(caller != address(0));

        // We must act as the product owner to call updateClosed. Determine coordinatorId and owner via controller
        // The controller.owner(uint256) overloads require a coordinatorId; get coordinatorId for this product
        uint256 coordId = controller.coordinatorFor(c);
        address ownerAddr = controller.owner(coordId);

        // Precondition: the computed owner must equal the provided caller to simulate owner invocation via onlyProductOwner
        // If they differ, we cannot perform the call as that caller; in that case we skip the mutating call and assert closed unchanged.
        bool preOwnerMatches = (ownerAddr == caller);

        bool reverted = false;
        bool closedBefore = c.closed();

        if (preOwnerMatches) {
            // We need to perform the external call as if msg.sender == ownerAddr. We cannot change msg.sender here,
            // but the framework guarantees this contract is the deployer and owner could be the controller owner —
            // to satisfy the rule we only attempt the call when this contract *is* the owner. So require that.
            // If this contract is not the owner, we instead ensure we do not attempt the state-changing call.
            if (address(this) == ownerAddr) {
                try c.updateClosed(newClosed) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            } else {
                // cannot call as owner, mark as reverted to indicate we didn't perform state change
                reverted = true;
            }
        }

        bool closedAfter = c.closed();

        // General rule:
        // If we successfully invoked updateClosed (i.e., preOwnerMatches and this contract is owner and call did not revert),
        // then closedAfter must equal newClosed. Otherwise closed must remain equal to closedBefore (no unexpected change).
        assert((preOwnerMatches && address(this) == ownerAddr && !reverted) ? (closedAfter == newClosed) : (closedAfter == closedBefore));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Single public test function: try to open a take for `account` with `amount`.
    // We act as `account` by requiring address(this) == account when we perform the state-changing call.
    function run(address account, UFixed18 amount) public payable {
        require(account != address(0));

        // Read pre-state (view): the account's pending open position taker amount
        C.PrePosition memory preBefore = c.pre(account);
        UFixed18 takerBefore = preBefore.openPosition.taker;

        bool reverted;

        // We only attempt the state-changing call when this contract equals the provided account
        // so that onlyAccountOrMultiInvoker / onlyAccountOwner style checks that require msg.sender==account pass.
        if (address(this) == account) {
            // Top-level state-changing call on c as required by the harness shape rules.
            // Use try/catch to record whether it reverted.
            try c.openTakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // If not acting as the account, we don't call and mark as reverted (call not performed)
            reverted = true;
        }

        // Read post-state
        C.PrePosition memory preAfter = c.pre(account);
        UFixed18 takerAfter = preAfter.openPosition.taker;

        // Assert the invariant: if the call was performed and did not revert, takerAfter == takerBefore + amount.
        // Otherwise (call reverted or not performed) the observed taker must be unchanged.
        // Note: use gt/lte methods from UFixed18Lib via public view comparisons provided by contract getters.
        // We express equality by checking both not greater and not less.
        bool equalAfterAdded;
        // takerAfter == takerBefore + amount  <=>  !(takerAfter < takerBefore + amount) && !(takerAfter > takerBefore + amount)
        UFixed18 sum = takerBefore.add(amount);
        bool notLess = !takerAfter.lt(sum);
        bool notGreater = !takerAfter.gt(sum);
        equalAfterAdded = notLess && notGreater;

        bool equalUnchanged;
        // takerAfter == takerBefore
        bool notLess0 = !takerAfter.lt(takerBefore);
        bool notGreater0 = !takerAfter.gt(takerBefore);
        equalUnchanged = notLess0 && notGreater0;

        assert((!reverted) ? equalAfterAdded : equalUnchanged);
    }

    // receive to allow holding ETH if needed by c in other tests
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We take the account address and amount as inputs. To perform the state-changing call
    // we require that this contract acts as the account (i.e., address(this) == account).
    // The function is payable to satisfy any potential collateral interactions, though not used here.
    function run(address account, UFixed18 amount) public payable {
        require(account != address(0));

        // Observe pre-state via public view: the account's PrePosition
        C.PrePosition memory preBefore = c.pre(account);
        UFixed18 takerBefore = preBefore.openPosition.taker;

        bool performed = false;
        bool reverted = false;

        if (address(this) == account) {
            // attempt the top-level state-changing call and record whether it reverted
            performed = true;
            try c.openTakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Observe post-state
        C.PrePosition memory preAfter = c.pre(account);
        UFixed18 takerAfter = preAfter.openPosition.taker;

        // Compute expected sum using the public UFixed18.add view via requiring equality through comparisons
        UFixed18 expected = takerBefore.add(amount);

        // equality checks: takerAfter == expected  and takerAfter == takerBefore
        bool afterEqExpected = (!takerAfter.lt(expected)) && (!takerAfter.gt(expected));
        bool afterEqBefore = (!takerAfter.lt(takerBefore)) && (!takerAfter.gt(takerBefore));

        // If we performed the call and it did not revert, taker must have increased exactly by amount.
        // Otherwise (call reverted or not performed) taker must be unchanged.
        assert(performed && !reverted ? afterEqExpected : afterEqBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We pass the account; this contract must act as that account to call openTakeFor as the account.
    // amount is passed as raw uint256 which we'll convert to UFixed18 by calling UFixed18.wrap inside the contract C when needed.
    // However, we cannot refer to UFixed18 type here (it's declared in the compilation unit), so use uint256 and pass through.
    function run(address account, uint256 amount) public payable {
        require(account == address(this)); // ensure this contract is the account so only authorization checks inside C depend on msg.sender

        // Read pre-state via public getter
        C.PrePosition memory preBefore = c.pre(account);
        uint256 takerBefore = preBefore.openPosition.taker; // UFixed18 is a user-defined value type over uint256; reading yields that type but ABI returns uint256

        bool reverted;
        // top-level state-changing call
        try c.openTakeFor(account, UFixed18.wrap(amount)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        C.PrePosition memory preAfter = c.pre(account);
        uint256 takerAfter = preAfter.openPosition.taker;

        // Expected after if succeeded: takerBefore + amount
        uint256 expected = takerBefore + amount;

        // If call did not revert, takerAfter must equal expected. If it reverted, takerAfter must equal takerBefore.
        assert(!reverted ? takerAfter == expected : takerAfter == takerBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Run as this contract being 'account'. amount is raw uint256 representing UFixed18.unwrap value.
    function run(address account, uint256 amount) public payable {
        // ensure we call as the account so authorization inside C that checks msg.sender == account holds
        require(account == address(this));

        // read pre-state via public accessor pre(account)
        (uint256 pre_oracleVersionBefore, uint256 pre_openMake_makerBefore, uint256 pre_openMake_takerBefore, uint256 pre_closeMake_makerBefore, uint256 pre_closeMake_takerBefore) = _readPre(account);
        uint256 takerBefore = pre_openMake_takerBefore; // openPosition.taker

        bool reverted;
        // top-level state-changing call: try calling openTakeFor as this contract
        try c.openTakeFor(account, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-state
        (uint256 pre_oracleVersionAfter, uint256 pre_openMake_makerAfter, uint256 pre_openMake_takerAfter, uint256 pre_closeMake_makerAfter, uint256 pre_closeMake_takerAfter) = _readPre(account);
        uint256 takerAfter = pre_openMake_takerAfter;

        // If call succeeded, openPosition.taker must have increased by exactly amount. If it reverted, it must be unchanged.
        assert(!reverted ? takerAfter == takerBefore + amount : takerAfter == takerBefore);
    }

    // Helper to read the nested PrePosition returned by c.pre(account).
    // We cannot name UFixed18 types here; the ABI exposes them as uint256 values in the tuple order.
    function _readPre(address account) internal view returns (
        uint256 oracleVersion,
        uint256 openMaker_maker,
        uint256 openMaker_taker,
        uint256 closeMaker_maker,
        uint256 closeMaker_taker
    ) {
        // c.pre(account) returns (PrePosition) which ABI-encodes as a tuple; directly call and destructure.
        // The exact layout: PrePosition { uint256 oracleVersion; Position openPosition; Position closePosition; }
        // Position { UFixed18 maker; UFixed18 taker; } each are uint256 in ABI.
        (oracleVersion, openMaker_maker, openMaker_taker, closeMaker_maker, closeMaker_taker) = c.pre(account);
    }

    receive() external payable {}
}

