    function run(bool useMake, address account, uint256 rawAmount) public payable {
        // normalize amount to UFixed18 representation: use rawAmount as the underlying integer (may be zero)
        // We cannot construct UFixed18 type directly here, but we can pass through as uint256 and rely on public functions.
        // Precondition: account must be this contract or any address; UParamProvider only restricts owner in some calls which we won't invoke.
        require(true);

