        uint256 latestVer = c.latestVersion();
        // If latestVersion is 0 then some operations (openMake) revert due to nonZeroVersionInvariant; allow both branches
        // We'll attempt both openMakeFor and openTakeFor depending on useMake flag.

        // Observe price at latestVersion via valueAtVersion -> returns Accumulator, not price; price only accessible via oracle through UPayoffProvider._sync which is internal.
        // However openTakeFor/openMakeFor compute positionFee = amount * latestOracleVersion.price.abs() * fee, and then call controller().collateral().settleAccount(...)
        // We cannot observe price directly; but we can detect whether positionFee was zero by checking whether amount == 0 (then fee zero) or fee == 0 from makerFee/takerFee getters.

        // Read fees
        UFixed18 makerF = c.makerFee();
        UFixed18 takerF = c.takerFee();

        // Decide amount: if rawAmount is large, clamp to avoid overflows in contract operations (but we cannot cast to UFixed18 here). We'll just use rawAmount as-is.
        uint256 amount = rawAmount;

        bool reverted;
        // Try the chosen action. We must call state-changing functions as top-level statements.
