        bool feeParamZero;
        if (useMake) {
            feeParamZero = (makerF == UFixed18Lib.ZERO);
        } else {
            feeParamZero = (takerF == UFixed18Lib.ZERO);
        }

        bool amountZero = (amount == 0);
        bool expectedZeroFee = amountZero || feeParamZero;

        // General rule: if expectedZeroFee then call MUST NOT revert (position fee zero should not cause collateral.settleAccount revert), otherwise may or may not revert.
        assert(!(expectedZeroFee && reverted));
    }

