contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take params to call openMakeFor or openTakeFor and observe fees via controller.collateral().fees
    // We will call openMakeFor when isMake==true, otherwise openTakeFor. We require amount>0 to make operation meaningful.
    function run(bool isMake, address account, uint256 rawAmount) public payable {
        require(rawAmount > 0);

        // map rawAmount into a UFixed18 by calling openMakeFor/openTakeFor which accept UFixed18 type (alias uint256)
        uint256 amount = rawAmount;

        // Read pre-fees from controller.collateral().fees(account)
        // Need to get controller from c.controller()
        IController controller = c.controller();
        ICollateral coll = controller.collateral();
        // read fee before (UFixed18)
        UFixed18 feesBefore = coll.fees(account);

        // perform the action and capture whether it reverted
        bool reverted;
        if (isMake) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // read fees after (may revert if function reverted? but reads are independent)
        UFixed18 feesAfter = coll.fees(account);

        // read latest oracle price absolute via c.currentVersion through payoff provider
        // We can observe that if the call succeeded and charged a position fee, then feesAfter <= feesBefore
        // Determine if a position fee would be non-zero: it depends on latest price.abs() and maker/taker fee.
        IOracleProvider.OracleVersion memory ver = c.currentVersion();
        Fixed18 priceAbs = ver.price.abs();
        UFixed18 makerFee = c.makerFee();
        UFixed18 takerFee = c.takerFee();

        // Compute theoretical position fee for the amount depending on isMake
        // positionFee = amount.mul(priceAbs).mul(makerOrTakerFee)
        UFixed18 posFee;
        if (isMake) {
            posFee = UFixed18Lib.mul(UFixed18.wrap(amount), UFixed18Lib.wrap(Fixed18Lib.abs(priceAbs)) ).mul(makerFee);
        } else {
            posFee = UFixed18Lib.mul(UFixed18.wrap(amount), UFixed18Lib.wrap(Fixed18Lib.abs(priceAbs)) ).mul(takerFee);
        }

        // General rule asserted:
        // If the call reverted then fees should be unchanged. If it succeeded and computed posFee == 0 then fees unchanged.
        // If it succeeded and posFee != 0 then feesAfter.unwrap() <= feesBefore.unwrap() (collateral fees become more negative or equal)
        if (reverted) {
            assert(feesAfter.eq(feesBefore));
        } else {
            if (posFee.isZero()) {
                assert(feesAfter.eq(feesBefore));
            } else {
