    // We test that openMakeFor/openTakeFor charge collateral fees when they should,
    // and never increase the recorded collateral.fees (i.e., fees become more negative or stay same).
    // Parameters: isMake selects openMakeFor (true) or openTakeFor (false), account is target, amount is raw uint.
    function run(bool isMake, address account, uint256 amount) public payable {
        require(amount > 0);

        // Obtain controller and collateral via public getters
        IController controller = c.controller();
        ICollateral coll = controller.collateral();

        // Read fees before
        UFixed18 feesBefore = coll.fees(account);

        // Read oracle price and fees to compute expected position fee
        // Use currentVersion() which is public on c (via UPayoffProvider)
        IOracleProvider.OracleVersion memory ver = c.currentVersion();
        Fixed18 price = ver.price;
        UFixed18 makerFee = c.makerFee();
        UFixed18 takerFee = c.takerFee();

        // Compute position fee as UFixed18: amount * |price.truncate to uint? |
        // price is Fixed18 (scaled by 1e18). To compute amount * |price| * fee as UFixed18,
        // compute: posFee = UFixed18.wrap(amount).mul( UFixed18.wrap(price.abs()) ).mul(chosenFee)
        // But price.abs() returns UFixed18 per Fixed18Lib.abs(), so reuse that.
        UFixed18 priceAbs = price.abs();
        UFixed18 amt = UFixed18.wrap(amount);
        UFixed18 expectedPosFee;
        if (isMake) {
            expectedPosFee = amt.mul(priceAbs).mul(makerFee);
        } else {
            expectedPosFee = amt.mul(priceAbs).mul(takerFee);
        }

        // Call the chosen function and record whether it reverted
        bool reverted;
        if (isMake) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read fees after
        UFixed18 feesAfter = coll.fees(account);

        // General rule asserted:
        // - If call reverted => fees unchanged.
        // - Else if expectedPosFee is zero => fees unchanged.
        // - Else (succeeded and expectedPosFee > 0) => feesAfter <= feesBefore.
        bool cond;
        if (reverted) {
            cond = feesAfter.eq(feesBefore);
        } else if (expectedPosFee.isZero()) {
            cond = feesAfter.eq(feesBefore);
        } else {
            cond = feesAfter.lte(feesBefore);
        }

        assert(cond);
    }

    receive() external payable {}
}

