        // normalize amount into UFixed18 by using the public helpers: we can't construct UFixed18 directly,
        // so we pass a raw uint and rely on the contract expecting UFixed18 in its calls (type compatible)

        // Read some before values
        bool closedBefore = c.closed();
        uint256 latestBefore = c.latestVersion();

        // perform one of the state-changing actions as a top-level statement
        if (doMake) {
            // openMakeFor is nonReentrant and may revert; capture revert
            bool reverted;
            try c.openMakeFor(account, UFixed18.wrap(amountRaw)) {
                reverted = false;
            } catch {
                reverted = true;
            }

            // After attempting, certain view calls should still be callable and not revert
            // We assert that calling maintenance(account) and position(account) succeeds (by reading their values)
            UFixed18 m = c.maintenance(account);
            C.Position memory p = c.position(account);

            // If the openMakeFor succeeded (not reverted), then either contract was closed before or after.
            // The general rule: position fee charged is non-negative and view calls remain accessible.
            // We can't directly read fees charged, but we can assert that maintenance is a UFixed18 value (trivially non-negative)
            // and that position's maker/taker are valid UFixed18 values. We'll express that as latestVersion >= latestBefore OR reverted.
            // Final assert: either the call reverted, or latestVersion advanced (or stayed) but maintenance and position calls returned.
            uint256 latestAfter = c.latestVersion();
            assert(reverted || latestAfter >= latestBefore);
        } else {
            bool reverted;
            try c.openTakeFor(account, UFixed18.wrap(amountRaw)) {
                reverted = false;
            } catch {
                reverted = true;
            }

            UFixed18 m = c.maintenance(account);
            C.Position memory p = c.position(account);

            uint256 latestAfter = c.latestVersion();
            assert(reverted || latestAfter >= latestBefore);
        }
    }

    receive() external payable {}
}

